INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (16,'61763',4,'EN',1,'Strengthen your abs with smart rebound power!','Introducing AbForge™, the must-have addition to your home gym. Engineered for effective ab training, it delivers targeted core workouts with automatic rebound assistance and adjustable resistance levels. Build strength, sculpt your stomach, and boost endurance – all from the comfort of your home!','https://s-mania.com/v1/en/abforge','https://s-mania.com/v1/en/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (17,'63138',4,'BG',0,'Укрепете коремните си мускули с умна възстановителна сила!','Представяме ви AbForge™, задължителното допълнение към вашата домашна фитнес зала. Проектиран за ефективно трениране на коремните мускули, той предлага целенасочени тренировки за ядрото с автоматична помощ при възстановяване и регулируеми нива на съпротивление. Изградете сила, оформете корема си и увеличете издръжливостта – всичко това от уюта на вашия дом!','https://s-mania.com/v1/bg/abforge','https://s-mania.com/v1/bg/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (18,'63133',4,'CZ',0,'Posilte své břišní svaly chytrou rebound silou!','Představujeme AbForge™, nezbytný doplněk vaší domácí posilovny. Navržen pro efektivní trénink břišních svalů, poskytuje cílené cvičení na střed těla s automatickou pomocí při odrazu a nastavitelnými úrovněmi odporu. Budujte sílu, tvarujte svůj žaludek a zvyšte vytrvalost – to vše z pohodlí vašeho domova!','https://s-mania.com/v1/cz/abforge','https://s-mania.com/v1/cz/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (19,'63139',4,'DE',0,'Stärken Sie Ihre Bauchmuskeln mit intelligenter Rückstoßkraft!','Präsentation von AbForge™, der unverzichtbaren Ergänzung für dein Home Gym. Entwickelt für effektives Bauchtraining, bietet es gezielte Core-Workouts mit automatischer Rückfederungshilfe und einstellbaren Widerstandsstufen. Stärke aufbauen, deinen Bauch formen und die Ausdauer steigern – alles bequem von zu Hause aus!','https://s-mania.de/v1/k/abforge','https://s-mania.de/v1/k/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (20,'65762',4,'EE',0,'Tugevda oma kõhulihaseid nutika tagasilöögi jõuga!','Tutvustame AbForge™-i, hädavajaliku täienduse sinu kodusesse jõusaali. Loodud tõhusaks kõhulihaste treeninguks, pakub see sihipäraseid keretreeninguid automaatse tagasikerimise abiga ja reguleeritavate takistustasemetega. Arenda jõudu, vormi oma','https://s-mania.com/v1/ee/abforge','https://s-mania.com/v1/ee/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (21,'63135',4,'GR',0,'Ενδυναμώστε τους κοιλιακούς σας με έξυπνη δύναμη επαναφοράς!','Παρουσιάζουμε το AbForge™, την απαραίτητη προσθήκη στο γυμναστήριο του σπιτιού σας. Σχεδιασμένο για αποτελεσματική εκπαίδευση κοιλιακών, προσφέρει στοχευμένες προπονήσεις πυρήνα με αυτόματη βοήθεια επαναφοράς και ρυθμιζόμενα επίπεδα αντίστασης. Δημιουργήστε δύναμη, σμιλέψτε την κοιλιά σας και ενισχύστε την αντοχή σας – όλα από την άνεση του σπιτιού σας!','https://s-mania.com/v1/gr/abforge','https://s-mania.com/v1/gr/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (22,'61766',4,'HR',0,'OJAČAJ SVOJE TRBUŠNJAKE UZ PAMETNU SNAGU POVRATNOG MEHANIZMA!','Predstavljamo AbForge™, neizostavan dodatak vašoj kućnoj teretani. Dizajniran za učinkovit trening trbušnih mišića, pruža ciljane vježbe za core s automatskom pomoći pri oporavku i podesivim razinama otpora. Izgradite snagu, oblikujte trbuh i povećajte izdržljivost – sve iz udobnosti svog doma!','https://s-mania.com/v1/hr/abforge','https://s-mania.com/v1/hr/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (23,'61764',4,'HU',0,'Erősítsd a hasizmaidat intelligens visszapattanó erővel!','Bemutatjuk az AbForge™-t, az otthoni edzőterem elengedhetetlen kiegészítőjét. A hatékony hasizom-edzéshez tervezett készülék célzott törzsedzéseket biztosít automatikus visszapattanási segítséggel és állítható ellenállási szintekkel. Építsen erőt, formálja a hasát és fokozza az állóképességet - mindezt otthonról, kényelmesen!','https://s-mania.com/v1/hu/abforge','https://s-mania.com/v1/hu/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (24,'63137',4,'IT',0,'Rafforza i tuoi addominali con il potere del rimbalzo intelligente!','Presentiamo AbForge™, l\'aggiunta indispensabile al tuo home gym. Progettato per un allenamento addominale efficace, offre allenamenti mirati per il core con assistenza al rimbalzo automatica e livelli di resistenza regolabili. Costruisci forza, scolpisci il tuo addome e aumenta la resistenza – tutto dal comfort di casa tua!','https://s-mania.it/v1/abforge','https://s-mania.it/v1/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (25,'63140',4,'LT',0,'Sustiprinkite savo pilvo raumenis su protinga atšokimo galia!','Pristatome AbForge™, būtinas priedas jūsų namų sporto salėje. Sukurtas efektyviam pilvo raumenų treniravimui, jis suteikia tikslinius core treniruotes su automatinėmis atšokimo pagalbos funkcijomis ir reguliuojamais pasipriešinimo lygiais. Stiprinkite jėgą, formuokite pilvą ir didinkite ištvermę – viską patogiai savo namuose!','https://s-mania.com/v1/lt/abforge','https://s-mania.com/v1/lt/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (26,'65763',4,'LV',0,'Stiprini savu vēderpresi ar viedu atsitiena jaudu!','Iepazīstinām ar AbForge™, obligātu papildinājumu jūsu mājas sporta zālei. Izstrādāts efektīviem vēdera muskuļu treniņiem, tas nodrošina mērķtiecīgus ķermeņa kodola treniņus ar automātisku atsitiena palīdzību un regulējamiem pretestības līmeņiem. Veidojiet spēku, veidojiet vēdera presi un uzlabojiet izturību – viss no jūsu mājas ērtībām!','https://s-mania.com/v1/lv/abforge','https://s-mania.com/v1/lv/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (27,'63136',4,'PL',0,'Wzmocnij swoje mięśnie brzucha dzięki inteligentnej mocy odbicia!','Przedstawiamy AbForge™, niezbędny element Twojej domowej siłowni. Zaprojektowany z myślą o skutecznym treningu mięśni brzucha, oferuje ukierunkowane ćwiczenia na rdzeń z automatyczną pomocą w odbiciu i regulowanymi poziomami oporu. Buduj siłę, rzeźb swoje brzuch i zwiększaj wytrzymałość – wszystko to w komfortowych warunkach swojego domu!','https://s-mania.com/v1/pl/abforge','https://s-mania.com/v1/pl/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (28,'61765',4,'RO',0,'Întărește-ți abdomenul cu putere de revenire inteligentă!','Vă prezentăm AbForge™, o completare indispensabilă a sălii dvs. de sport de acasă. Proiectat pentru un antrenament eficient al abdomenului, acesta oferă antrenamente de bază direcționate cu asistență automată la revenire și niveluri de rezistență reglabile. Dezvoltă-ți forța, sculptează-ți abdomenul și stimulează rezistența - toate din confortul casei tale!','https://s-mania.com/v1/ro/abforge','https://s-mania.com/v1/ro/abforge/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
