INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (54,'65089',6,'ES',0,'Renueva tu entrada en un abrir y cerrar de ojos.','¿Tu entrada de coches se ve desgastada? DrivewayPRO™ es la solución definitiva para restaurar y proteger superficies de asfalto y hormigón. Con su resistencia a las inclemencias del tiempo, cambios de temperatura, agrietamiento y daños por UV, DrivewayPRO™ no solo mejora la apariencia de tu entrada, sino que también ofrece un sellado y protección impermeables de larga duración.','https://s-mania.com/v1/es/drivewaypro','https://s-mania.com/v1/es/drivewaypro/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
