INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (56,'59656',6,'HR',0,'Obnovite svoj prilaz u tren oka','Izgleda li vaš prilaz istrošeno? DrivewayPRO™ je ultimativno rješenje za obnovu i zaštitu asfaltnih i betonskih površina. Sa svojom otpornošću na loše vremenske uvjete, temperaturne promjene, pucanje i UV oštećenja, DrivewayPRO™ ne samo da poboljšava izgled vašeg prilaza, već također pruža dugotrajnu vodonepropusnost i zaštitu.','https://s-mania.com/v1/hr/drivewaypro','https://s-mania.com/v1/hr/drivewaypro/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (57,'61375',6,'HU',0,'Egy pillanat alatt megújítja a felhajtót','Kopottnak tűnik a felhajtója? A DrivewayPRO™ a végső megoldás az aszfalt- és betonfelületek helyreállítására és védelmére. A kedvezőtlen időjárással, hőmérséklet-változásokkal, repedésekkel és UV-károsodással szembeni ellenálló képességével a DrivewayPRO™ nem csak a felhajtóút megjelenését javítja, hanem hosszú távú vízszigetelést és védelmet is biztosít.','https://s-mania.com/v1/hu/drivewaypro','https://s-mania.com/v1/hu/drivewaypro/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (58,'61379',6,'IT',0,'Rinnovate il vostro vialetto in un attimo','Il vostro vialetto sembra usurato? DrivewayPRO™ è la soluzione definitiva per ripristinare e proteggere le superfici in asfalto e cemento. Grazie alla sua resistenza alle intemperie, agli sbalzi di temperatura, alle crepe e ai danni causati dai raggi UV, DrivewayPRO™ non solo migliora l\'aspetto del vostro vialetto, ma fornisce anche un\'impermeabilizzazione e una protezione durature.','https://s-mania.it/v1/drivewaypro','https://s-mania.it/v1/drivewaypro/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (59,'61384',6,'LT',0,'Akimirksniu atnaujinkite važiuojamąją dalį','Ar jūsų važiuojamoji dalis atrodo nusidėvėjusi? \"DrivewayPRO™\" yra geriausias sprendimas asfalto ir betono paviršiams atkurti ir apsaugoti. Dėl atsparumo nepalankioms oro sąlygoms, temperatūrų pokyčiams, įtrūkimams ir UV spinduliams DrivewayPRO™ ne tik pagerina jūsų važiuojamosios dalies išvaizdą, bet ir užtikrina ilgalaikę hidroizoliaciją ir apsaugą.','https://s-mania.com/v1/lt/drivewaypro','https://s-mania.com/v1/lt/drivewaypro/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (60,'61383',6,'LV',0,'Atjaunojiet savu piebraucamo ceļu vienā mirklī','Vai jūsu piebraucamais ceļš izskatās nolietojies? DrivewayPRO™ ir vislabākais risinājums asfalta un betona virsmu atjaunošanai un aizsardzībai. Ar savu noturību pret nelabvēlīgiem laikapstākļiem, temperatūras izmaiņām, plaisāšanu un UV starojuma bojājumiem DrivewayPRO™ ne tikai uzlabo Jūsu brauktuves izskatu, bet arī nodrošina ilglaicīgu hidroizolāciju un aizsardzību.','https://s-mania.com/v1/lv/drivewaypro','https://s-mania.com/v1/lv/drivewaypro/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (61,'61382',6,'NL',0,'Vernieuw je oprit in een handomdraai','Ziet je oprit er versleten uit? DrivewayPRO™ is de ultieme oplossing voor het herstellen en beschermen van asfalt en betonnen oppervlakken. Met zijn weerstand tegen guur weer, temperatuurschommelingen, scheuren en UV-schade verbetert DrivewayPRO™ niet alleen het uiterlijk van uw oprit, maar biedt het ook langdurige waterdichting en bescherming.','https://s-mania.nl/v1/drivewaypro','https://s-mania.nl/v1/drivewaypro/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (62,'61378',6,'PL',0,'Odnów swój podjazd w mgnieniu oka','Czy Twój podjazd wygląda na zużyty? DrivewayPRO™ to najlepsze rozwiązanie do renowacji i ochrony powierzchni asfaltowych i betonowych. Dzięki odporności na niekorzystne warunki pogodowe, zmiany temperatury, pękanie i uszkodzenia spowodowane promieniowaniem UV, DrivewayPRO™ nie tylko poprawia wygląd podjazdu, ale także zapewnia długotrwałą wodoodporność i ochronę.','https://s-mania.com/v1/pl/drivewaypro','https://s-mania.com/v1/pl/drivewaypro/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
