INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (171,'63740',13,'BG',0,'Умен storage, който носи спокойствие на вашия плот.','Постигнете безeffortна организация и естествена елегантност във вашия дом с този стилен органайзер за плотове. Изработен от здрави материали, той предлага както красота, така и издръжливост, като същевременно поддържа вашите основни принадлежности подредени. Просторният чекмеджен добавя удобно достъпно място и допълнително пространство за вашите ежедневни вещи, правейки вашето пространство по-чисто, по-спокойно и перфектно оформено.','https://s-mania.com/v1/bg/woodydraw','https://s-mania.com/v1/bg/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (172,'63735',13,'CZ',0,'Chytré úložiště, které přináší klid na váš pracovní stůl.','Přineste do svého domova bez námahy organizaci a přirozenou eleganci s tímto stylovým organizérem na pult. Vyroben z pevného materiálu, nabízí krásu i odolnost a zároveň udržuje vaše nezbytnosti na správném místě. Prostorná zásuvka poskytuje snadný přístup a extra místo pro vaše každodenní věci, což dělá váš prostor čistější, klidnější a dokonale uspořádaný.','https://s-mania.com/v1/cz/woodydraw','https://s-mania.com/v1/cz/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (173,'63741',13,'DE',0,'Intelligente Aufbewahrung, die Ruhe auf Ihre Arbeitsplatte bringt.','Bringen Sie mühelose Ordnung und natürliche Eleganz in Ihr Zuhause mit diesem stilvollen Küchenarbeitsplatten-Organizer. Hergestellt aus robusten Materialien bietet er sowohl Schönheit als auch Langlebigkeit und hält Ihre Essentials ordentlich an ihrem Platz. Die geräumige Schublade sorgt für bequemen Zugang und zusätzlichen Platz für Ihre Alltagsgegenstände, was Ihren Raum sauberer, ruhiger und perfekt organisiert macht.','https://s-mania.de/v1/k/woodydraw','https://s-mania.de/v1/k/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (174,'65738',13,'EE',0,'Nutikas säilitamine, mis toob teie tööpinnale rahu.','Too oma koju muretu organiseerimist ja loomulikku elegantsi selle stiilse töötasapinna organiseerijaga. Valmistatud vastupidavatest materjalidest, pakub see nii ilu kui ka vastupidavust, hoides samas sinu tähtsad asjad korralikult paigas. Avatud sahtel tagab mugava ligipääsu ning lisaruumi igapäevaste esemete jaoks, muutes sinu ruumi puhtamaks, rahulikumaks ja ideaalselt korraldatud.','https://s-mania.com/v1/ee/woodydraw','https://s-mania.com/v1/ee/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (175,'63737',13,'GR',0,'Έξυπνη αποθήκευση που φέρνει ηρεμία στον πάγκο σας.','Φέρτε εύκολη οργάνωση και φυσική κομψότητα στον χώρο σας με αυτόν τον κομψό ορθοστάτη πάγκου. Κατασκευασμένος από ανθεκτικά υλικά, προσφέρει ομορφιά και αντοχή, κρατώντας τα απαραίτητα σας τακτοποιημένα. Ο ευρύχωρος συρτάρης προσφέρει εύκολη πρόσβαση και επιπλέον χώρο για τα καθημερινά σας αντικείμενα, κάνοντάς τον χώρο σας πιο καθαρό, ήρεμο και τέλεια οργανωμένο.','https://s-mania.com/v1/gr/woodydraw','https://s-mania.com/v1/gr/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (176,'62363',13,'HR',0,'Pametno pohranjivanje koje donosi mir na vašu radnu površinu.','Unesite jednostavnu organizaciju i prirodnu eleganciju u svoj dom s ovim elegantnim organizatorom za radnu površinu. Izrađen od čvrstih materijala, nudi ljepotu i izdržljivost, a istovremeno uredno drži vaše potrepštine na svom mjestu. Prostrana ladica pruža praktičan pristup i dodatni prostor za vaše svakodnevne predmete, čineći vaš prostor čišćim, mirnijim i savršeno uređenim.','https://s-mania.com/v1/hr/woodydraw','https://s-mania.com/v1/hr/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (177,'62364',13,'HU',0,'Okos tároló, amely nyugalmat hoz a pultra.','Hozzon könnyed szervezést és természetes eleganciát otthonába ezzel a stílusos pult szervezővel. Robusztus anyagokból készült, egyszerre kínál szépséget és tartósságot, miközben rendezetten a helyén tartja a legfontosabb dolgokat. A tágas fiók kényelmes hozzáférést és extra helyet biztosít a mindennapi tárgyak számára, tisztábbá, nyugodtabbá és tökéletesen rendezetté téve terét.','https://s-mania.com/v1/hu/woodydraw','https://s-mania.com/v1/hu/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (178,'63739',13,'IT',0,'Un sistema di archiviazione intelligente che porta calma al tuo piano di lavoro.','Porta un\'organizzazione senza sforzo e un\'eleganza naturale nella tua casa con questo elegante organizer da bancone. Realizzato con materiali resistenti, unisce bellezza e durata mantenendo i tuoi oggetti essenziali in ordine. Il cassetto spazioso offre un accesso comodo e ulteriore spazio per i tuoi articoli quotidiani, rendendo il tuo ambiente più pulito, tranquillo e perfettamente organizzato.','https://s-mania.it/v1/woodydraw','https://s-mania.it/v1/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (179,'63742',13,'LT',0,'Išmanus saugojimas, kuris suteikia ramybę jūsų stalviršiui.','Atneškite nesudėtingą tvarką ir natūralų eleganciją savo namams su šiuo stilingu stalviršio organizatoriumi. Pagamintas iš tvirtų medžiagų, jis suteikia ne tik grožį, bet ir ilgaamžiškumą, tuo pačiu išlaikydamas jūsų svarbiausius daiktus tvarkingai. Erdvus stalčius užtikrina patogų pritaikymą ir papildomą vietą kasdieniams daiktams, taip padarydamas jūsų erdvę tvarkingesnę, ramesnę ir idealiai sutvarkytą.','https://s-mania.com/v1/lt/woodydraw','https://s-mania.com/v1/lt/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (180,'65739',13,'LV',0,'Vieda glabāšana, kas rada mieru tavā virtuves darba virsmā.','Pievienojiet vieglu organizāciju un dabisku eleganci savām mājām ar šo stilīgo galda organizētāju. Izgatavots no izturīgiem materiāliem, tas piedāvā gan skaistumu, gan izturību, vienlaikus uzturot jūsu nepieciešamās lietas kārtībā. Plašā atvilktne nodrošina ērtu piekļuvi un papildus vietu ikdienas lietām, padarot jūsu telpu tīrāku, mierīgāku un perfektā kārtībā.','https://s-mania.com/v1/lv/woodydraw','https://s-mania.com/v1/lv/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (181,'63738',13,'PL',0,'Inteligentne przechowywanie, które wprowadza spokój na Twojej blacie.','Wprowadź bezwysiłkową organizację i naturalną elegancję do swojego domu dzięki temu stylowemu organizerowi na blacie. Wykonany z solidnych materiałów, łączy w sobie piękno i trwałość, jednocześnie utrzymując Twoje niezbędne rzeczy w porządku. Przestronna szuflada zapewnia wygodny dostęp i dodatkową przestrzeń na codzienne przedmioty, sprawiając, że Twoja przestrzeń staje się czystsza, spokojniejsza i doskonale zorganizowana.','https://s-mania.com/v1/pl/woodydraw','https://s-mania.com/v1/pl/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (182,'62365',13,'RO',0,'Depozitare inteligentă care aduce calm blatului dvs.','Aduceți organizarea fără efort și eleganța naturală în casa dvs. cu acest organizator de blat elegant. Fabricat din materiale rezistente, acesta oferă atât frumusețe, cât și durabilitate, în timp ce vă păstrează elementele esențiale la locul lor. Sertarul spațios adaugă acces convenabil și spațiu suplimentar pentru obiectele dvs. de zi cu zi, făcând spațiul dvs. mai curat, mai calm și perfect aranjat.','https://s-mania.com/v1/ro/woodydraw','https://s-mania.com/v1/ro/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (183,'62563',13,'RS',0,'Pametno skladištenje koje donosi mir na vašu radnu površinu.','Donosite beznaporno organizovanje i prirodnu eleganciju u svoj dom sa ovim stilskim organizatorom za radnu površinu. Napravljen od čvrstih materijala, nudi i lepotu i izdržljivost dok vaši osnovni predmeti ostaju uredno na svom mestu. Prostrana fioka omogućava lak pristup i dodatni prostor za vaše svakodnevne stvari, čineći vaš prostor čistijim, smirenijim i savršeno uređenim.','https://s-mania.com/v1/rs/woodydraw','https://s-mania.com/v1/rs/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (184,'63734',13,'SI',0,'Pametno shranjevanje, ki prinaša mir na vašo delovno površino.','V svoj dom vnesite brezskrbno organizacijo in naravno eleganco s tem stilskim organizatorjem za pult. Izdelan je iz trpežnih materialov, zato združuje lep videz in dolgotrajno vzdržljivost ter poskrbi, da so vaši najnujnejši predmeti vedno urejeno na svojem mestu. Prostoren predal omogoča priročen dostop in dodatni prostor za vsakodnevne stvari, vaš prostor pa postane bolj urejen, umirjen in dovršen.','https://smania.si/v1/woodydraw','https://smania.si/v1/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
INSERT INTO `landings` (`id`, `external_id`, `product_id`, `country_code`, `is_master`, `title`, `description`, `landing_url`, `product_image_url`, `last_synced_at`, `version`, `created_at`, `updated_at`) VALUES (185,'63736',13,'SK',0,'Inteligentné úložisko, ktoré prináša pokoj na vašu pracovnú dosku.','Prineste bez námahy organizáciu a prirodzenú eleganciu do vášho domova s týmto štýlovým organizérom na pracovnej doske. Vyrobený z pevných materiálov, ponúka krásu a odolnosť a zároveň udržiava vaše nevyhnutnosti na správnom mieste. Priestranná zásuvka poskytuje pohodlný prístup a extra miesto pre vaše každodenné veci, čím robí váš priestor čistejším, pokojnejším a dokonale usporiadaným.','https://s-mania.com/v1/sk/woodydraw','https://s-mania.com/v1/sk/woodydraw/product-img/var-1.webp','2026-09-14 08:14:47',0,'2026-09-14 08:14:47','2026-09-14 08:14:47');
